        if key not in data:
            errors.append(f"eksik: {key}")
        elif type(data[key]) is not expected:
            errors.append(f"tür: {key}")
    for key in data:
        if key not in hints:
            errors.append(f"fazla: {key}")
    return sorted(errors)

